<?php
final class DoctorMessagingService
{
 public function __construct(private PDO $db,private array $user){if(permission_profile($user,$db)!=='doctor' && (($user['role']??'')!=='nurse'||!has_permission('clinical_messages',$user,$db)))throw new RuntimeException('Physician messaging requires an authorized Nurse or Doctor.');}
 private function member(int $id): void {$q=$this->db->prepare("SELECT COUNT(*) FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id WHERE c.id=? AND p.user_id=? AND c.conversation_type='doctor_consultation' AND c.status='active' AND (SELECT COUNT(*) FROM conversation_participants pair WHERE pair.conversation_id=c.id)=2 AND EXISTS(SELECT 1 FROM conversation_participants pair JOIN users nurse ON nurse.id=pair.user_id WHERE pair.conversation_id=c.id AND nurse.role='nurse' AND nurse.status='active' AND nurse.self_service_only=0) AND EXISTS(SELECT 1 FROM conversation_participants pair JOIN users physician ON physician.id=pair.user_id JOIN admin_profiles profile ON profile.user_id=physician.id WHERE pair.conversation_id=c.id AND profile.profile='doctor' AND physician.status='active')");$q->execute([$id,$this->user['id']]);if(!(int)$q->fetchColumn())throw new RuntimeException('This physician conversation is outside your participant scope.');$q=$this->db->prepare("SELECT u.* FROM conversation_participants p JOIN users u ON u.id=p.user_id WHERE p.conversation_id=? AND u.role='nurse'");$q->execute([$id]);$nurse=$q->fetch();if(!$nurse||!has_permission('clinical_messages',$nurse,$this->db))throw new RuntimeException('Nurse clinical messaging authority is unavailable.');}
 public function threads(): array {$q=$this->db->prepare("SELECT c.id,c.title,c.updated_at FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id WHERE p.user_id=? AND c.conversation_type='doctor_consultation' AND c.status='active' ORDER BY c.updated_at DESC LIMIT 50");$q->execute([$this->user['id']]);$rows=$q->fetchAll();return array_values(array_filter($rows,function($row){try{$this->member((int)$row['id']);return true;}catch(RuntimeException $e){return false;}}));}
 public function contacts(): array {$doctor=permission_profile($this->user,$this->db)==='doctor';$rows=$this->db->query("SELECT u.* FROM users u LEFT JOIN admin_profiles p ON p.user_id=u.id WHERE u.status='active' AND ".($doctor?"u.role='nurse' AND u.self_service_only=0":"p.profile='doctor'")." ORDER BY u.first_name,u.last_name LIMIT 100")->fetchAll();return array_values(array_filter($rows,fn($row)=>!$doctor||has_permission('clinical_messages',$row,$this->db)));}
 public function messages(int $id): array {$this->member($id);$this->db->prepare('UPDATE messages SET read_at=NOW() WHERE conversation_id=? AND sender_id<>? AND read_at IS NULL')->execute([$id,$this->user['id']]);$q=$this->db->prepare('SELECT m.id,m.sender_id,m.message_body,m.created_at,m.read_at,u.first_name,u.last_name,u.profile_picture FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=? ORDER BY m.id DESC LIMIT 100');$q->execute([$id]);return array_reverse($q->fetchAll());}
 public function start(int $recipient): int {
  if($recipient===(int)$this->user['id'])throw new InvalidArgumentException('Select another authorized clinical contact.');
  $this->db->beginTransaction();try{$q=$this->db->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$q->execute([$this->user['id']]);$q->fetch();
   $q=$this->db->prepare("SELECT * FROM users WHERE id=? AND status='active'");$q->execute([$recipient]);$contact=$q->fetch(PDO::FETCH_ASSOC);$doctor=permission_profile($this->user,$this->db)==='doctor';if(!$contact || ($doctor ? ($contact['role']!=='nurse'||!has_permission('clinical_messages',$contact,$this->db)) : permission_profile($contact,$this->db)!=='doctor'))throw new InvalidArgumentException('Physician conversations connect authorized Nurses and Doctors only.');
   $q=$this->db->prepare("SELECT c.id FROM conversations c JOIN conversation_participants p1 ON p1.conversation_id=c.id AND p1.user_id=? JOIN conversation_participants p2 ON p2.conversation_id=c.id AND p2.user_id=? WHERE c.conversation_type='doctor_consultation' AND c.status='active' LIMIT 1");$q->execute([$this->user['id'],$recipient]);$id=$q->fetchColumn();
   if(!$id){$this->db->prepare("INSERT INTO conversations(conversation_type,title,created_by) VALUES ('doctor_consultation','Physician consultation communication',?)")->execute([$this->user['id']]);$id=(int)$this->db->lastInsertId();$q=$this->db->prepare('INSERT INTO conversation_participants(conversation_id,user_id) VALUES (?,?)');$q->execute([$id,$this->user['id']]);$q->execute([$id,$recipient]);}
   $this->db->commit();return (int)$id;
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
 }
 public function send(int $id,string $message): void {
  $message=trim($message);if($message===''||mb_strlen($message)>4000)throw new InvalidArgumentException('Messages must contain 1–4000 characters.');
  $this->db->beginTransaction();try{$this->member($id);$this->db->prepare("INSERT INTO messages(conversation_id,sender_id,message_body,message_type) VALUES (?,?,?,'text')")->execute([$id,$this->user['id'],$message]);$this->db->prepare('UPDATE conversations SET updated_at=NOW() WHERE id=?')->execute([$id]);$this->db->prepare("INSERT INTO activity_logs(user_id,action,module,details) VALUES (?,'Physician conversation message sent','messages',?)")->execute([$this->user['id'],'Conversation #'.$id.'; message contents excluded from audit.']);$this->db->prepare("INSERT INTO notifications(user_id,type,title,message,link) SELECT user_id,'message','Clinical coordination message','A clinical colleague sent you a message.',? FROM conversation_participants WHERE conversation_id=? AND user_id<>?")->execute([app_url('pages/doctor_messages.php?thread='.$id),$id,$this->user['id']]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
 }
}
